void mainImage( out vec4 O, vec2 u )
{
    vec2 U = u/R.y;
    O*=0.;
    for( int i; i < N*N; i++)                                                               // display particles
        O[int(P(i).z)] += smoothstep( 1.5/R.y,0., length( P(i).xy - U ) -.02 );

    if (U.y<.08) O = O*.3 + max(1.2 - R.y* abs( T(vec2(u.x,N))/float(N*N)*.08 - U.y ),0.);  // display stats
}
